#!/usr/bin/env python3
"""
Round 119b (culprits-tiles-more), 30 September 2026. Upload after round118b_tiles.py.

- scripts/attacks_plain.py (new): the attacks rows' files in plain English
  (attacks/plain/): labels from a table of the sources' own terms, longer texts
  machine-translated with Argos Translate on the build machine (kept, so each
  day's run translates only what is new; CIMI's cases take several days),
  Brazil's states by name, record dates as dates, CIMI's families of violence,
  Front Line Defenders' tags in English; the Pastoral Land Commission's areas in
  conflict as municipality shapes from the owner's cgaz-boundaries copy.
- scripts/homicides.py (new): homicide rates by country (World Bank, UNODC's
  figures), case points from Chicago, Los Angeles, New York and The Washington
  Post's 50 cities (map archives), Colombia's police records by town, and
  murders in Wikidata.
- scripts/boards.py (new): board members, chairs and chief executives of the
  500 largest companies from Wikidata, and the ties between companies.
- scripts/troutwood_layers.py: Wreckers worldwide grouped by Corporate Watch's
  own directory sections, with why each section is on its list.
- scripts/global_witness.py: country totals no longer add the chart's map
  position; columns named.
- scripts/wjp_discrimination.py: each edition's score and rank kept.
- scripts/rte.py: every trade flow of each year, not only the largest.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/attacks_plain.py': '',
    'scripts/homicides.py': '',
    'scripts/boards.py': '',
    'scripts/troutwood_layers.py': '',
    'scripts/global_witness.py': '',
    'scripts/wjp_discrimination.py': '',
    'scripts/rte.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
